// Authored NOT_RUN.
use kni_core::cff_fill::{audit,SourceFill,RingRole,FillAudit};
use kni_core::reference_slice::{DrawnGlyph,ReferenceRing,Point,Span};
#[test]fn direction_and_fill_intent(){let o=Point{x:0.,y:0.};let g=DrawnGlyph{glyph_id:"A".into(),rings:vec![ReferenceRing{start:o,spans:vec![Span::Line{end:Point{x:10.,y:0.}},Span::Line{end:Point{x:0.,y:10.}},Span::Line{end:o}]}]};assert_eq!(audit(&g,SourceFill::NonZero,&[RingRole::FilledBoundary]),vec![FillAudit::NonZeroNeedsEquivalenceProof,FillAudit::DirectionObserved(0)]);assert_eq!(audit(&g,SourceFill::NonZero,&[RingRole::CounterBoundary]),vec![FillAudit::NonZeroNeedsEquivalenceProof,FillAudit::DirectionMismatch(0)]);assert_eq!(audit(&g,SourceFill::EvenOdd,&[RingRole::Unknown]),vec![FillAudit::UnknownRole(0)]);}
#[test]fn crossing_rings_observed_unresolved(){let o=Point{x:0.,y:0.};let r=ReferenceRing{start:o,spans:vec![Span::Line{end:Point{x:10.,y:0.}},Span::Line{end:Point{x:0.,y:10.}},Span::Line{end:o}]};let g=DrawnGlyph{glyph_id:"A".into(),rings:vec![r.clone(),r]};let result=audit(&g,SourceFill::EvenOdd,&[RingRole::FilledBoundary,RingRole::FilledBoundary]);assert!(result.contains(&FillAudit::CompoundIntersectionUnresolved(0,1)));}
#[test]fn curved_pairs_do_not_escape_unresolved_audit(){let o=Point{x:0.,y:0.};let ring=ReferenceRing{start:o,spans:vec![Span::Cubic{control_one:Point{x:10.,y:0.},control_two:Point{x:0.,y:10.},end:o}]};let g=DrawnGlyph{glyph_id:"O".into(),rings:vec![ring.clone(),ring]};let report=audit(&g,SourceFill::EvenOdd,&[RingRole::CounterBoundary,RingRole::FilledBoundary]);assert!(report.contains(&FillAudit::CompoundIntersectionUnresolved(0,1)));assert!(report.contains(&FillAudit::CurvedDirectionUnresolved(0)));assert!(report.contains(&FillAudit::CurvedDirectionUnresolved(1)));}
